CREATE TABLE public.barber_schedule_days (barber_id uuid NOT NULL REFERENCES public.barbers(id) ON DELETE CASCADE, weekday smallint NOT NULL CHECK (weekday BETWEEN 0 AND 6), closed boolean NOT NULL DEFAULT false, periods jsonb NOT NULL DEFAULT '[]', PRIMARY KEY(barber_id,weekday));
GRANT SELECT ON public.barber_schedule_days TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.barber_schedule_days TO authenticated; GRANT ALL ON public.barber_schedule_days TO service_role;
ALTER TABLE public.barber_schedule_days ENABLE ROW LEVEL SECURITY;
CREATE POLICY schedule_days_read ON public.barber_schedule_days FOR SELECT USING(true);
CREATE POLICY schedule_days_admin ON public.barber_schedule_days FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.barber_lunch_overrides (barber_id uuid PRIMARY KEY REFERENCES public.barbers(id) ON DELETE CASCADE, starts_time time, ends_time time, CHECK ((starts_time IS NULL AND ends_time IS NULL) OR (starts_time IS NOT NULL AND ends_time IS NOT NULL AND ends_time > starts_time)));
GRANT SELECT ON public.barber_lunch_overrides TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.barber_lunch_overrides TO authenticated; GRANT ALL ON public.barber_lunch_overrides TO service_role;
ALTER TABLE public.barber_lunch_overrides ENABLE ROW LEVEL SECURITY;
CREATE POLICY lunch_overrides_read ON public.barber_lunch_overrides FOR SELECT USING(true);
CREATE POLICY lunch_overrides_admin ON public.barber_lunch_overrides FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.schedule_absences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text NOT NULL CHECK(scope IN ('shop','team','barber')), barber_id uuid REFERENCES public.barbers(id), starts_on date NOT NULL, ends_on date NOT NULL, weekdays integer[], starts_time time, ends_time time, kind text NOT NULL DEFAULT 'ausente' CHECK(kind IN ('ausente','ferias','atestado','emergencia')), note text NOT NULL DEFAULT '', created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_on>=starts_on AND ends_on<=starts_on+366), CHECK((scope='barber')=(barber_id IS NOT NULL)), CHECK(weekdays IS NULL OR (cardinality(weekdays)>0 AND weekdays <@ ARRAY[0,1,2,3,4,5,6])), CHECK((starts_time IS NULL AND ends_time IS NULL) OR (starts_time IS NOT NULL AND ends_time IS NOT NULL AND ends_time>starts_time)));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.schedule_absences TO authenticated; GRANT ALL ON public.schedule_absences TO service_role;
ALTER TABLE public.schedule_absences ENABLE ROW LEVEL SECURITY;
CREATE POLICY schedule_absences_admin ON public.schedule_absences FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY schedule_absences_self_read ON public.schedule_absences FOR SELECT TO authenticated USING(scope IN ('shop','team') OR EXISTS(SELECT 1 FROM public.barbers b WHERE b.id=barber_id AND b.user_id=auth.uid()));
CREATE POLICY schedule_absences_self_write ON public.schedule_absences FOR INSERT TO authenticated WITH CHECK(scope='barber' AND kind IN ('emergencia','atestado') AND created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.barbers b WHERE b.id=barber_id AND b.user_id=auth.uid() AND b.active AND b.approved_at IS NOT NULL));
CREATE POLICY schedule_absences_self_update ON public.schedule_absences FOR UPDATE TO authenticated USING(created_by=auth.uid() AND scope='barber' AND EXISTS(SELECT 1 FROM public.barbers b WHERE b.id=barber_id AND b.user_id=auth.uid())) WITH CHECK(created_by=auth.uid() AND scope='barber' AND kind IN ('emergencia','atestado') AND EXISTS(SELECT 1 FROM public.barbers b WHERE b.id=barber_id AND b.user_id=auth.uid()));
CREATE POLICY schedule_absences_self_delete ON public.schedule_absences FOR DELETE TO authenticated USING(created_by=auth.uid() AND scope='barber' AND EXISTS(SELECT 1 FROM public.barbers b WHERE b.id=barber_id AND b.user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.schedule_absence_matches(_start date,_end date,_weekdays integer[],_day date) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT _day BETWEEN _start AND _end AND (_weekdays IS NULL OR extract(dow FROM _day)::int=ANY(_weekdays)) $$;
CREATE OR REPLACE FUNCTION public.effective_schedule_periods(_barber uuid,_day date) RETURNS TABLE(opens_at time,closes_at time) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT p.opens_at,p.closes_at FROM public.business_periods p WHERE p.weekday=extract(dow FROM _day) AND NOT COALESCE((SELECT closed FROM public.business_hours WHERE weekday=p.weekday),false) AND NOT EXISTS(SELECT 1 FROM public.barber_schedule_days b WHERE b.barber_id=_barber AND b.weekday=p.weekday)
UNION ALL SELECT greatest(p.opens_at,(j->>'o')::time),least(p.closes_at,(j->>'c')::time) FROM public.business_periods p JOIN public.barber_schedule_days b ON b.weekday=p.weekday AND b.barber_id=_barber CROSS JOIN LATERAL jsonb_array_elements(b.periods) j WHERE p.weekday=extract(dow FROM _day) AND NOT b.closed AND NOT COALESCE((SELECT closed FROM public.business_hours WHERE weekday=p.weekday),false) AND (j->>'o')::time < p.closes_at AND (j->>'c')::time > p.opens_at $$;
CREATE OR REPLACE FUNCTION public.effective_lunch(_barber uuid,_day date) RETURNS TABLE(ls timestamptz,le timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (_day+COALESCE(b.lunch_start,o.starts_time,s.lunch_start)) AT TIME ZONE 'America/Sao_Paulo', (_day+COALESCE(b.lunch_start,o.starts_time,s.lunch_start)+CASE WHEN o.barber_id IS NOT NULL THEN o.ends_time-o.starts_time ELSE s.lunch_end-s.lunch_start END) AT TIME ZONE 'America/Sao_Paulo' FROM public.barbers b CROSS JOIN public.operation_settings s LEFT JOIN public.barber_lunch_overrides o ON o.barber_id=b.id WHERE b.id=_barber AND s.id=1 AND (CASE WHEN o.barber_id IS NOT NULL THEN o.starts_time ELSE s.lunch_start END) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.barber_absences a WHERE a.barber_id=_barber AND a.kind='almoco' AND _day BETWEEN a.starts_on AND a.ends_on) $$;
CREATE OR REPLACE FUNCTION public.get_busy_slots(_barber_id uuid,_day date) RETURNS TABLE(starts_at timestamptz,ends_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT a.starts_at,a.ends_at FROM public.appointments a WHERE a.barber_id=_barber_id AND a.status<>'cancelado' AND a.starts_at>=_day::timestamp AT TIME ZONE 'America/Sao_Paulo' AND a.starts_at<(_day+1)::timestamp AT TIME ZONE 'America/Sao_Paulo'
UNION ALL SELECT (_day+COALESCE(x.starts_time,'00:00'::time)) AT TIME ZONE 'America/Sao_Paulo', CASE WHEN x.starts_time IS NULL THEN (_day+1)::timestamp AT TIME ZONE 'America/Sao_Paulo' ELSE (_day+x.ends_time) AT TIME ZONE 'America/Sao_Paulo' END FROM public.barber_absences x WHERE x.barber_id=_barber_id AND _day BETWEEN x.starts_on AND x.ends_on
UNION ALL SELECT (_day+COALESCE(x.starts_time,'00:00'::time)) AT TIME ZONE 'America/Sao_Paulo',CASE WHEN x.starts_time IS NULL THEN (_day+1)::timestamp AT TIME ZONE 'America/Sao_Paulo' ELSE (_day+x.ends_time) AT TIME ZONE 'America/Sao_Paulo' END FROM public.schedule_absences x WHERE (x.scope IN ('shop','team') OR x.barber_id=_barber_id) AND public.schedule_absence_matches(x.starts_on,x.ends_on,x.weekdays,_day)
UNION ALL SELECT ls,le FROM public.effective_lunch(_barber_id,_day) $$;
CREATE OR REPLACE FUNCTION public.get_available_slots(_barber_id uuid,_day date,_duration integer,_service_ids uuid[] DEFAULT NULL) RETURNS TABLE(starts_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH s AS(SELECT * FROM public.operation_settings WHERE id=1), lim AS(SELECT min(latest_start_time) t FROM public.services WHERE _service_ids IS NOT NULL AND id=ANY(_service_ids)), lunch AS(SELECT * FROM public.effective_lunch(_barber_id,_day)), cand AS(SELECT DISTINCT gs st FROM public.effective_schedule_periods(_barber_id,_day) p CROSS JOIN s CROSS JOIN LATERAL generate_series((_day+p.opens_at) AT TIME ZONE 'America/Sao_Paulo',(_day+p.closes_at) AT TIME ZONE 'America/Sao_Paulo',make_interval(mins=>s.slot_step_minutes)) gs WHERE NOT EXISTS(SELECT 1 FROM public.shop_blocked_dates WHERE day=_day) AND public.is_barber_bookable(_barber_id) AND _duration>0 AND (s.max_advance_days IS NULL OR _day<=(now() AT TIME ZONE 'America/Sao_Paulo')::date+s.max_advance_days)) SELECT c.st FROM cand c,s,lim WHERE c.st>=now()+make_interval(mins=>s.min_advance_minutes) AND c.st>now() AND (lim.t IS NULL OR c.st<=(_day+lim.t) AT TIME ZONE 'America/Sao_Paulo') AND NOT EXISTS(SELECT 1 FROM lunch l WHERE c.st>=l.ls AND c.st<l.le) AND NOT EXISTS(SELECT 1 FROM public.get_busy_slots(_barber_id,_day) b WHERE b.starts_at<c.st+make_interval(mins=>_duration) AND b.ends_at>c.st AND NOT EXISTS(SELECT 1 FROM lunch l WHERE l.ls=b.starts_at AND l.le=b.ends_at)) ORDER BY c.st $$;
CREATE OR REPLACE FUNCTION public.save_scoped_hours(_scope text,_barber uuid,_days jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d jsonb; p jsonb; target uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso restrito.' USING ERRCODE='42501'; END IF; IF _scope NOT IN ('shop','team','barber') OR (_scope='barber' AND _barber IS NULL) THEN RAISE EXCEPTION 'Selecione a aplicação.'; END IF; FOR d IN SELECT value FROM jsonb_array_elements(_days) LOOP IF (d->>'weekday')::int NOT BETWEEN 0 AND 6 THEN RAISE EXCEPTION 'Dia inválido.'; END IF; IF NOT (d->>'closed')::boolean AND jsonb_array_length(d->'periods')=0 THEN RAISE EXCEPTION 'Adicione um período.'; END IF; FOR p IN SELECT value FROM jsonb_array_elements(d->'periods') LOOP IF (p->>'c')::time<=(p->>'o')::time THEN RAISE EXCEPTION 'Fechamento deve ser depois da abertura.'; END IF; END LOOP; IF EXISTS(SELECT 1 FROM jsonb_array_elements(d->'periods') WITH ORDINALITY a(v,i),jsonb_array_elements(d->'periods') WITH ORDINALITY b(v,i) WHERE a.i<b.i AND (a.v->>'o')::time<(b.v->>'c')::time AND (a.v->>'c')::time>(b.v->>'o')::time) THEN RAISE EXCEPTION 'Períodos sobrepostos.'; END IF; IF _scope='shop' THEN UPDATE public.business_hours SET closed=(d->>'closed')::boolean WHERE weekday=(d->>'weekday')::int; DELETE FROM public.business_periods WHERE weekday=(d->>'weekday')::int; IF NOT (d->>'closed')::boolean THEN INSERT INTO public.business_periods(weekday,opens_at,closes_at) SELECT (d->>'weekday')::int,(v->>'o')::time,(v->>'c')::time FROM jsonb_array_elements(d->'periods') v; END IF; ELSE FOR target IN SELECT id FROM public.barbers WHERE archived_at IS NULL AND (_scope='team' OR id=_barber) LOOP INSERT INTO public.barber_schedule_days VALUES(target,(d->>'weekday')::int,(d->>'closed')::boolean,d->'periods') ON CONFLICT(barber_id,weekday) DO UPDATE SET closed=excluded.closed,periods=excluded.periods; END LOOP; END IF; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.save_scoped_lunch(_scope text,_barber uuid,_start time,_end time) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso restrito.' USING ERRCODE='42501'; END IF; IF _scope NOT IN ('shop','team','barber') OR (_scope='barber' AND _barber IS NULL) THEN RAISE EXCEPTION 'Selecione a aplicação.'; END IF; IF (_start IS NULL)<>(_end IS NULL) OR _end<=_start THEN RAISE EXCEPTION 'Informe início e fim válidos.'; END IF; IF _scope='shop' THEN UPDATE public.operation_settings SET lunch_start=_start,lunch_end=_end WHERE id=1; ELSE INSERT INTO public.barber_lunch_overrides SELECT id,_start,_end FROM public.barbers WHERE archived_at IS NULL AND (_scope='team' OR id=_barber) ON CONFLICT(barber_id) DO UPDATE SET starts_time=excluded.starts_time,ends_time=excluded.ends_time; UPDATE public.barbers SET lunch_start=NULL WHERE archived_at IS NULL AND (_scope='team' OR id=_barber); END IF; END $$;
REVOKE ALL ON FUNCTION public.save_scoped_hours(text,uuid,jsonb),public.save_scoped_lunch(text,uuid,time,time) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_scoped_hours(text,uuid,jsonb),public.save_scoped_lunch(text,uuid,time,time) TO authenticated,service_role;